#!/bin/bash
set -e
DIR=/opt/hermes-chat-agent
mkdir -p $DIR/chat_agent
cd $DIR
base64 -d > /opt/hermes-chat-agent/chat_agent/chat_agent.py <<'B64EOF'

B64EOF
base64 -d > /opt/hermes-chat-agent/chat_agent/scripts.json <<'B64EOF'

B64EOF
base64 -d > /opt/hermes-chat-agent/chat_agent/objections.json <<'B64EOF'

B64EOF
base64 -d > /opt/hermes-chat-agent/chat_agent/sales_funnel.json <<'B64EOF'

B64EOF
base64 -d > /opt/hermes-chat-agent/chat_agent/intents.json <<'B64EOF'

B64EOF
base64 -d > /opt/hermes-chat-agent/config.json <<'B64EOF'
ewogICJjbGllbnRfaWQiOiAiNUtkdDUzSFloUnE0bVQ2MTBUcWUiLAogICJjbGllbnRfc2VjcmV0IjogIkVMOXdaNXVSUzlFOTlLNHllM2RyQU95RS1OdnpWZ0JQbXcxeTVCYUkiLAogICJ1c2VyX2lkIjogNDMxMDM2MTY5LAogICJnaF9vd25lciI6ICJiaXpuZXMxOTgwMTEtb3BzIiwKICAiZ2hfcmVwbyI6ICJhdml0by1kYXNoYm9hcmQiCn0=
B64EOF

cat > /etc/default/hermes-chat-agent <<'ENVEOF'
TELEGRAM_BOT_TOKEN=8945148552:AAFUALok5KUV39JlsvavoD6_GypJ2UycNhQ
TELEGRAM_CHAT_ID=1915169528
ENVEOF

cat > /etc/systemd/system/hermes-chat-agent.service <<'UNITEOF'
[Unit]
Description=Avito chat auto-responder
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
WorkingDirectory=/opt/hermes-chat-agent
EnvironmentFile=/etc/default/hermes-chat-agent
ExecStart=/usr/bin/python3 /opt/hermes-chat-agent/chat_agent.py poll
Restart=always
RestartSec=20
StandardOutput=append:/var/log/hermes-chat-agent.log
StandardError=append:/var/log/hermes-chat-agent.log

[Install]
WantedBy=multi-user.target
UNITEOF

systemctl daemon-reload
systemctl enable hermes-chat-agent >/dev/null 2>&1
systemctl restart hermes-chat-agent
sleep 8
echo "=== STATUS ==="
systemctl is-active hermes-chat-agent
echo "=== LOG ==="
tail -n 12 /var/log/hermes-chat-agent.log 2>/dev/null || echo no log
echo "=== DONE ==="
